<script setup lang="ts">
import { onMounted, ref } from "vue";
import { http } from "@/utils/http";
type Row = Record<string, any>;
const tab = ref("shares"); const shares = ref<Row[]>([]); const rooms = ref<Row[]>([]); const loading = ref(false); const saving = ref(false); const error = ref(""); const dialog = ref(false); const form = ref({ targetId: "", permission: "VIEW", expiresAt: "", password: "", maxAccessCount: 0, allowDownload: false, note: "" });
async function load() { loading.value = true; error.value = ""; try { const [s, r] = await Promise.all([http.get<unknown, unknown>("/shares"), http.get<unknown, unknown>("/rooms")]); shares.value = Array.isArray(s) ? s as Row[] : []; rooms.value = Array.isArray(r) ? r as Row[] : []; } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "分享协作数据加载失败"; } finally { loading.value = false; } }
async function revoke(row: Row) { if (!row.id || !window.confirm("确认撤销该分享链接吗？")) return; try { await http.post(`/shares/${row.id}/actions/revoke`); await load(); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "撤销分享失败"; } }
async function createShare() { if (!form.value.targetId.trim() || !form.value.expiresAt) { error.value = "目标和过期时间不能为空"; return; } saving.value = true; try { await http.post("/shares", { data: { ...form.value, targetId: form.value.targetId.trim(), maxAccessCount: form.value.maxAccessCount || null } }); dialog.value = false; form.value = { targetId: "", permission: "VIEW", expiresAt: "", password: "", maxAccessCount: 0, allowDownload: false, note: "" }; await load(); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "创建分享失败"; } finally { saving.value = false; } }
onMounted(load);
</script>
<template><main class="p-4 md:p-6"><div class="flex justify-between items-start mb-6"><div><h1 class="text-2xl font-semibold">分享与协作</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">管理分享链接、协作 Room 和协作状态。</p></div><div class="flex gap-2"><el-button type="primary" @click="dialog = true">创建分享</el-button><el-button :loading="loading" @click="load">刷新</el-button></div></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="mb-4"/><el-card shadow="never"><el-tabs v-model="tab"><el-tab-pane label="分享链接" name="shares"><el-empty v-if="!shares.length" description="暂无分享链接"/><el-table v-else :data="shares" stripe><el-table-column prop="resourceId" label="目标 Resource / Collection" min-width="220"/><el-table-column prop="permission" label="权限" width="130"/><el-table-column prop="expiresAt" label="过期时间" min-width="180"/><el-table-column prop="accessCount" label="访问次数" width="120"/><el-table-column prop="creator" label="创建者" width="140"/><el-table-column prop="status" label="状态" width="120"/><el-table-column label="操作" width="100"><template #default="{ row }"><el-button link type="danger" @click="revoke(row)">撤销</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="Room" name="rooms"><el-empty v-if="!rooms.length" description="暂无协作 Room"/><el-table v-else :data="rooms" stripe><el-table-column prop="name" label="Room 名称" min-width="200"/><el-table-column prop="mediaOrQueue" label="媒体 / 队列" min-width="180"/><el-table-column prop="owner" label="房主" width="140"/><el-table-column prop="memberCount" label="成员数" width="100"/><el-table-column prop="status" label="状态" width="130"/><el-table-column prop="createdAt" label="创建时间 / 最近活动" min-width="180"/></el-table></el-tab-pane><el-tab-pane label="协作" name="collaboration"><el-empty description="选择 Room 后查看成员、消息和事件"/><el-alert title="权限修改应使用明确 Role Selector，并产生审计事件" type="info" :closable="false" show-icon/></el-tab-pane></el-tabs></el-card><el-dialog v-model="dialog" title="创建分享" width="560px"><el-form label-position="top"><el-form-item label="目标 Resource / Collection" required><el-input v-model="form.targetId" placeholder="输入目标 ID"/></el-form-item><el-form-item label="权限"><el-select v-model="form.permission" class="w-full"><el-option label="查看" value="VIEW"/><el-option label="查看 + 下载" value="VIEW_DOWNLOAD"/><el-option label="评论（如支持）" value="COMMENT"/></el-select></el-form-item><el-form-item label="过期时间" required><el-date-picker v-model="form.expiresAt" type="datetime" class="w-full"/></el-form-item><el-form-item label="访问次数上限"><el-input-number v-model="form.maxAccessCount" :min="0"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" show-password placeholder="可选"/></el-form-item><el-form-item><el-switch v-model="form.allowDownload" active-text="允许下载"/></el-form-item><el-form-item label="备注"><el-input v-model="form.note" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="dialog = false">取消</el-button><el-button type="primary" :loading="saving" @click="createShare">创建</el-button></template></el-dialog></main></template>
